import 'package:flutter_bloc/flutter_bloc.dart';

/// 카운터 Cubit - 가장 간단한 상태 관리
/// 
/// Cubit은 Event 없이 메서드 호출로 상태를 변경합니다.
/// 간단한 로직에 적합합니다.
class CounterCubit extends Cubit<int> {
  // 초기 상태를 생성자에서 super로 전달
  CounterCubit() : super(0);

  /// 카운터 증가
  void increment() {
    // emit()으로 새로운 상태를 발행
    // state는 현재 상태 값
    emit(state + 1);
  }

  /// 카운터 감소
  void decrement() {
    if (state > 0) {
      emit(state - 1);
    }
  }

  /// 카운터 초기화
  void reset() => emit(0);

  /// 특정 값으로 설정
  void setValue(int value) => emit(value);
}

import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';
import 'counter_cubit.dart';

/// 카운터 페이지 - Cubit과 UI 연결
class CounterPage extends StatelessWidget {
  const CounterPage({super.key});

  @override
  Widget build(BuildContext context) {
    // BlocProvider로 Cubit 인스턴스 제공
    return BlocProvider(
      // create: Cubit 인스턴스 생성
      create: (context) => CounterCubit(),
      child: const CounterView(),
    );
  }
}

/// 카운터 뷰 - 실제 UI
class CounterView extends StatelessWidget {
  const CounterView({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Cubit Counter')),
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            const Text('카운터 값:', style: TextStyle(fontSize: 18)),
            const SizedBox(height: 8),

            // BlocBuilder: 상태 변화에 따라 UI 리빌드
            BlocBuilder<CounterCubit, int>(
              builder: (context, count) {
                return Text(
                  '$count',
                  style: const TextStyle(
                    fontSize: 48,
                    fontWeight: FontWeight.bold,
                  ),
                );
              },
            ),

            const SizedBox(height: 24),

            // 버튼들
            Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                // context.read<T>(): Cubit 인스턴스 접근 (리빌드 없음)
                ElevatedButton(
                  onPressed: () => context.read<CounterCubit>().decrement(),
                  child: const Icon(Icons.remove),
                ),
                const SizedBox(width: 16),
                ElevatedButton(
                  onPressed: () => context.read<CounterCubit>().increment(),
                  child: const Icon(Icons.add),
                ),
                const SizedBox(width: 16),
                ElevatedButton(
                  onPressed: () => context.read<CounterCubit>().reset(),
                  child: const Icon(Icons.refresh),
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }
}

// main.dart에서 사용
void main() {
  runApp(
    const MaterialApp(
      home: CounterPage(),
    ),
  );
}

import 'package:equatable/equatable.dart';
import 'package:flutter_bloc/flutter_bloc.dart';

// ===== Events =====
/// 인증 관련 이벤트들
abstract class AuthEvent extends Equatable {
  const AuthEvent();
  @override
  List<Object?> get props => [];
}

class LoginRequested extends AuthEvent {
  final String email;
  final String password;

  const LoginRequested({required this.email, required this.password});

  @override
  List<Object?> get props => [email, password];
}

class LogoutRequested extends AuthEvent {}

class AuthCheckRequested extends AuthEvent {}

// ===== States =====
/// 인증 상태들
abstract class AuthState extends Equatable {
  const AuthState();
  @override
  List<Object?> get props => [];
}

class AuthInitial extends AuthState {}

class AuthLoading extends AuthState {}

class Authenticated extends AuthState {
  final String userId;
  final String email;

  const Authenticated({required this.userId, required this.email});

  @override
  List<Object?> get props => [userId, email];
}

class Unauthenticated extends AuthState {}

class AuthError extends AuthState {
  final String message;

  const AuthError(this.message);

  @override
  List<Object?> get props => [message];
}

// ===== Bloc =====
class AuthBloc extends Bloc<AuthEvent, AuthState> {
  final AuthRepository _authRepository;

  AuthBloc({required AuthRepository authRepository})
      : _authRepository = authRepository,
        super(AuthInitial()) {
    // 이벤트 핸들러 등록
    on<LoginRequested>(_onLoginRequested);
    on<LogoutRequested>(_onLogoutRequested);
    on<AuthCheckRequested>(_onAuthCheckRequested);
  }

  /// 로그인 요청 처리
  Future<void> _onLoginRequested(
    LoginRequested event,
    Emitter<AuthState> emit,
  ) async {
    emit(AuthLoading());

    try {
      final user = await _authRepository.login(
        email: event.email,
        password: event.password,
      );

      emit(Authenticated(userId: user.id, email: user.email));
    } catch (e) {
      emit(AuthError(e.toString()));
    }
  }

  /// 로그아웃 요청 처리
  Future<void> _onLogoutRequested(
    LogoutRequested event,
    Emitter<AuthState> emit,
  ) async {
    await _authRepository.logout();
    emit(Unauthenticated());
  }

  /// 인증 상태 확인
  Future<void> _onAuthCheckRequested(
    AuthCheckRequested event,
    Emitter<AuthState> emit,
  ) async {
    final user = await _authRepository.getCurrentUser();
    if (user != null) {
      emit(Authenticated(userId: user.id, email: user.email));
    } else {
      emit(Unauthenticated());
    }
  }
}

// ===== Repository (예시) =====
class User {
  final String id;
  final String email;
  User({required this.id, required this.email});
}

class AuthRepository {
  Future<User> login({required String email, required String password}) async {
    await Future.delayed(const Duration(seconds: 1));
    // 실제 로그인 로직
    return User(id: '123', email: email);
  }

  Future<void> logout() async {
    await Future.delayed(const Duration(milliseconds: 500));
  }

  Future<User?> getCurrentUser() async {
