  }
}

import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';
import 'auth_bloc.dart';

class LoginPage extends StatefulWidget {
  const LoginPage({super.key});

  @override
  State<LoginPage> createState() => _LoginPageState();
}

class _LoginPageState extends State<LoginPage> {
  final _emailController = TextEditingController();
  final _passwordController = TextEditingController();

  @override
  void dispose() {
    _emailController.dispose();
    _passwordController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return BlocProvider(
      create: (context) => AuthBloc(
        authRepository: AuthRepository(),
      ),
      child: Scaffold(
        appBar: AppBar(title: const Text('로그인')),
        body: Padding(
          padding: const EdgeInsets.all(16),
          // BlocConsumer = BlocListener + BlocBuilder
          child: BlocConsumer<AuthBloc, AuthState>(
            // listener: 사이드 이펙트 처리 (네비게이션, 스낵바 등)
            listener: (context, state) {
              if (state is Authenticated) {
                // 로그인 성공 → 홈으로 이동
                Navigator.of(context).pushReplacementNamed('/home');
              } else if (state is AuthError) {
                // 에러 → 스낵바 표시
                ScaffoldMessenger.of(context).showSnackBar(
                  SnackBar(
                    content: Text(state.message),
                    backgroundColor: Colors.red,
                  ),
                );
              }
            },
            // listenWhen: 특정 조건에서만 listener 실행 (선택)
            listenWhen: (previous, current) {
              return current is Authenticated || current is AuthError;
            },
            // builder: UI 빌드
            builder: (context, state) {
              return Column(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  TextField(
                    controller: _emailController,
                    decoration: const InputDecoration(
                      labelText: '이메일',
                      border: OutlineInputBorder(),
                    ),
                    enabled: state is! AuthLoading,
                  ),
                  const SizedBox(height: 16),
                  TextField(
                    controller: _passwordController,
                    decoration: const InputDecoration(
                      labelText: '비밀번호',
                      border: OutlineInputBorder(),
                    ),
                    obscureText: true,
                    enabled: state is! AuthLoading,
                  ),
                  const SizedBox(height: 24),
                  SizedBox(
                    width: double.infinity,
                    height: 48,
                    child: ElevatedButton(
                      onPressed: state is AuthLoading
                          ? null
                          : () {
                              context.read<AuthBloc>().add(
                                LoginRequested(
                                  email: _emailController.text,
                                  password: _passwordController.text,
                                ),
                              );
                            },
                      child: state is AuthLoading
                          ? const SizedBox(
                              width: 24,
                              height: 24,
                              child: CircularProgressIndicator(
                                strokeWidth: 2,
                                color: Colors.white,
                              ),
                            )
                          : const Text('로그인'),
                    ),
                  ),
                ],
              );
            },
            // buildWhen: 특정 조건에서만 리빌드 (선택)
            buildWhen: (previous, current) {
              return current is AuthLoading ||
                  current is AuthInitial ||
                  current is Unauthenticated;
            },
          ),
        ),
      ),
    );
  }
}

// BlocListener만 사용하는 예시
class ListenerOnlyExample extends StatelessWidget {
  const ListenerOnlyExample({super.key});

  @override
  Widget build(BuildContext context) {
    return BlocListener<AuthBloc, AuthState>(
      listener: (context, state) {
        // UI를 빌드하지 않고 사이드 이펙트만 처리
        if (state is AuthError) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(content: Text(state.message)),
          );
        }
      },
      child: const SomeOtherWidget(),
    );
  }
}

class SomeOtherWidget extends StatelessWidget {
  const SomeOtherWidget({super.key});
  @override
  Widget build(BuildContext context) => const SizedBox();
}

